/**
 * Profile
 * @param {*} param0 
 * @returns 
 */
const Profile = ({ addr, emojiId, emojies, message }) => {
  const [data, setData] = useState()

  const getProfile = async (addr) => {
    const myHeaders = new Headers()
    myHeaders.append('Content-Type', `application/json`)
    myHeaders.append('Accept', `application/json`)
    myHeaders.append('Mode', `no-cors`)

    const requestOptions = {
      method: 'POST',
      headers: myHeaders,
      body: JSON.stringify({
        query: `query MyQuery {
  search_profiles(
    args: {search: "${addr}"}
    limit: 1
  ) {
    fullName
    name
    id
    profileImages {
      src
    }
  }
}`,
      }),
    }
    const response = await fetch(`${process.env.NEXT_PUBLIC_API_ENDPOINT}`, requestOptions)
    if (!response.ok) {
      throw new Response('Failed to ', { status: 500 })
    }
    const data = await response.json()
    setData(data)
    return data
  }

  useEffect(() => {
    getProfile(addr).then(console.log)
  }, [])

  if (!data)
    return (
      <>
        <figure className={`${styles.pfp} d-f-c flex-column grid--gap-050`}>
          <img alt={`Default PFP`} src={DefaultPFP.src} className={`rounded`} />
          <figcaption>@username</figcaption>
        </figure>
      </>
    )

  return (
    <div  className={`${styles.pfp} d-f-c flex-row grid--gap-1`}>
      <figure>
        <img
          alt={data.data.search_profiles[0].fullName}
          src={`${data.data.search_profiles[0].profileImages.length > 0 ? data.data.search_profiles[0].profileImages[0].src : 'https://ipfs.io/ipfs/bafkreiatl2iuudjiq354ic567bxd7jzhrixf5fh5e6x6uhdvl7xfrwxwzm'}`}
          className={`rounded`}
        />
        <img
          src={`/emoji/${emojies.filter((filterItem) => filterItem.emojiId === emojiId)[0].emoji}.svg`}
          alt={`${process.env.NEXT_PUBLIC_NAME}`}
        />
      </figure>
              <figcaption className={`d-flex flex-column grid--gap-050`}>
          <b title={data.data.search_profiles[0].id}>@{data.data.search_profiles[0].name}</b>
          <small>{message}</small>
        </figcaption>
    </div>
  )
}
